function routeInfo() {
  const path = location.hash.replace(/^#\/?/, '').split('?')[0];
  const parts = path.split('/').filter(Boolean);
  if (!parts.length) return { area: 'web', page: 'home', extra: '' };
  return { area: parts[0], page: parts[1] || 'home', extra: parts.slice(2).join('/') };
}
function routeTo(path) { location.hash = `#/${path}`; window.scrollTo(0, 0); }
function moneySort(a, b) { return a.priceNum - b.priceNum; }
function statusClass(status) { return `status-${String(status).toLowerCase().replaceAll(' ', '-').replaceAll('_', '-')}`; }
function statusBadge(status) { return `<span class="status ${statusClass(status)}">${status}</span>`; }
function toast(message, type = 'success') {
  const region = document.getElementById('toast-region');
  const node = document.createElement('div'); node.className = `toast ${type === 'error' ? 'error' : ''}`;
  node.innerHTML = `${icon(type === 'error' ? 'close' : 'check')}<span>${message}</span>`;
  region.append(node); setTimeout(() => node.remove(), 3200);
}
