    <section class="section"><div class="section-head"><div><span class="eyebrow">Cập nhật liên tục</span><h2>Xe mới đăng</h2><p>Những lựa chọn đáng xem trong hôm nay</p></div><a class="btn btn-outline" href="#/web/search">Xem tất cả ${icon('arrow')}</a></div><div class="grid grid-4">${vehicleData.slice(0,4).map(vehicleCard).join('')}</div></section>
