function renderDetail(id) {
  const car = vehicleData.find(x => x.id === Number(id)) || vehicleData[0];
  return `${siteHeader()}<main id="main-content" class="container"><div class="page-heading"><div><p class="muted"><a href="#/web/search">Mua xe</a> / ${car.name}</p><h1 style="font-size:28px">${car.name}</h1><p class="muted">${icon('pin')} ${car.location} · Tin đăng mẫu #AO-${car.id}</p></div><button class="btn btn-outline" data-action="save-vehicle" data-id="${car.id}">${icon('heart')} ${savedIds.has(car.id)?'Đã lưu':'Lưu xe'}</button></div><div class="detail-layout"><section><img class="detail-main-photo" src="${photo(car.photo,1200)}" alt="${car.name}"><div class="thumb-row">${[car.photo,'photo-1503376780353-7e6692767b70','photo-1552519507-da3b142c6e3d'].map((p,i)=>`<img src="${photo(p,220)}" alt="Ảnh xe ${i+1}" data-action="change-main-photo" data-src="${photo(p,1200)}">`).join('')}</div><div class="surface surface-pad" style="margin-top:18px"><h2>Thông tin xe</h2><div class="detail-specs">${[['Năm sản xuất',car.year],['Số km đã đi',car.km],['Hộp số',car.transmission],['Nhiên liệu',car.fuel],['Kiểu thân xe','SUV'],['Số chỗ ngồi','5 chỗ'],['Xuất xứ','Trong nước'],['Tình trạng','Đã qua sử dụng'],['Màu sắc','Trắng']].map(([a,b])=>`<div class="spec"><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="divider"></div><h3>Mô tả từ người bán</h3><p class="muted">Xe sử dụng gia đình, bảo dưỡng định kỳ. Nội thất sạch sẽ, vận hành ổn định. Người mua vui lòng xem xe trực tiếp và kiểm tra thông tin trước khi giao dịch.</p><p class="tiny muted">Thông tin do người bán khai báo, cần được kiểm tra thực tế.</p></div><div class="surface surface-pad" style="margin-top:18px"><h2>Xe tương tự</h2><div class="grid grid-2">${vehicleData.filter(x=>x.id!==car.id).slice(0,2).map(vehicleCard).join('')}</div></div></section><aside class="surface seller-panel"><span class="eyebrow">Giá bán tham khảo</span><div class="vehicle-price" style="font-size:27px;margin:7px 0 16px">${car.price}</div><div class="seller-profile-head"><span class="avatar">${car.seller.slice(0,1)}</span><div><h3>${car.seller}</h3><span class="tiny muted">${car.type} · ${statusBadge('Verified')}</span></div></div><div class="divider"></div><p class="tiny muted">Thông tin liên hệ sẽ được chia sẻ trực tiếp với người bán sau khi bạn chủ động yêu cầu.</p><button class="btn" style="width:100%" data-action="contact-seller">${icon('user')} Liên hệ người bán</button><button class="btn btn-outline" style="width:100%;margin-top:8px" data-action="create-deposit" data-vehicle-id="${car.id}">Đặt cọc giữ xe</button><div class="divider"></div><button class="btn btn-quiet btn-sm" data-action="report-listing">Báo cáo tin đăng</button><div class="notice" style="margin-top:14px">Không chuyển tiền trước khi xác minh xe, người bán và điều khoản giao dịch.</div></aside></div></main>${siteFooter()}`;
}
