  const groups = [['TỔNG QUAN', [['dashboard','Tổng quan','home'],['analytics','Analytics & báo cáo','chart']]], ['VẬN HÀNH', [['listings','Tin đăng','car'],['moderation','Kiểm duyệt & báo cáo','shield'],['users','Người dùng','user'],['verification','Xác minh hồ sơ','check'],['deposits','Đặt cọc','layers'],['salons','Showroom','home']]], ['NỘI DUNG', [['content','Nội dung','file'],['media','Thư viện media','layers'],['menus','Quản lý menu','layers'],['banners','Banner & slide','layers'],['campaigns','Chiến dịch','chart'],['seo','SEO','search'],['tags','Tags & aliases','layers']]], ['DỮ LIỆU & HỆ THỐNG', [['catalog','Automotive Catalog','car'],['import-export','Nhập / xuất Catalog','download'],['attributes','Thuộc tính xe','settings'],['search-terms','Từ khóa tìm kiếm','search'],['notifications','Thông báo','bell'],['templates','Mẫu thông báo','file'],['support','Hỗ trợ khách hàng','user'],['legal','Nội dung pháp lý','file'],['roles','Vai trò & quyền','shield'],['security','Bảo mật','shield'],['integrations','Tích hợp','layers'],['audit','Audit log','file'],['archive','Lưu trữ & retention','clock'],['settings','Cấu hình hệ thống','settings']]]];
  groups.find(([label]) => label === 'NỘI DUNG')[1].splice(4, 0, ['ad-placements','Vị trí quảng cáo','layers']);
