function renderRows(rows,page) {
  if (!rows.length) return `<tr><td colspan="8"><div class="empty-state"><h3>Không có dữ liệu khớp</h3><p>Thay đổi từ khóa hoặc bộ lọc.</p></div></td></tr>`;
  return rows.map(r=>`<tr><td><input type="checkbox" aria-label="Chọn ${r.code}"></td><td><strong>${r.code}</strong></td><td>${r.name}</td><td>${r.owner}</td><td>${r.location}</td><td>${r.updated}</td><td>${statusBadge(r.status)}</td><td><div class="table-actions"><button class="icon-btn" title="Xem chi tiết" aria-label="Xem chi tiết" data-action="view-row" data-id="${r.ref||r.code}" data-name="${r.name}">${icon('eye')}</button>${['listings','moderation','verification'].includes(page)?`<button class="btn btn-outline btn-sm" data-action="approve-row" data-id="${r.ref||r.code}">Duyệt</button>`:''}${page==='deposits'?`${r.status==='Pending Payment'?`<button class="btn btn-outline btn-sm" data-action="deposit-received-proof" data-id="${r.ref}">Nhận chứng từ</button>`:''}${r.status==='Verifying'?`<button class="btn btn-sm" data-action="deposit-confirm-paid" data-id="${r.ref}">Xác nhận đã nhận cọc</button>`:''}<button class="btn btn-outline btn-sm" data-action="deposit-notify" data-id="${r.ref}">Thông báo</button>`:''}<button class="icon-btn" title="Thêm thao tác" aria-label="Thêm thao tác" data-action="edit-row" data-name="${r.name}">${icon('dots')}</button></div></td></tr>`).join('');
}
