function openLegalDocumentEditor(documentId) {
  editingLegalDocumentId=documentId;
  const document=legalDocuments.find(item=>item.id===documentId);
  if(!document)return;
  const body=`<form id="legal-document-form" class="grid"><div class="form-grid"><div class="field"><label for="legal-title">Tiêu đề *</label><input id="legal-title" name="title" required maxlength="100" value="${escapeHtml(document.title)}"></div><div class="field"><label for="legal-version">Phiên bản</label><input id="legal-version" name="version" maxlength="20" value="${escapeHtml(document.version||'1.0')}"></div><div class="field field-full"><label for="legal-summary">Mô tả ngắn *</label><input id="legal-summary" name="summary" required maxlength="180" value="${escapeHtml(document.summary)}"></div><div class="field"><label for="legal-effective-date">Ngày cập nhật / hiệu lực</label><input id="legal-effective-date" name="updatedAt" type="date" value="${escapeHtml(document.updatedAt||new Date().toISOString().slice(0,10))}"></div><div class="field"><label class="filter-check"><input name="published" type="checkbox" ${document.status==='Published'?'checked':''}> Xuất bản công khai</label></div></div><div class="field"><label for="legal-body">Nội dung văn bản *</label><textarea id="legal-body" name="body" required class="legal-editor-textarea" placeholder="Viết nội dung; để một dòng trống giữa các mục/đoạn.">${escapeHtml(document.body)}</textarea><span class="tiny muted">Dùng văn bản thuần; một dòng trống để tách đoạn. Không chèn HTML hoặc script.</span></div><div class="notice">Bản hiện tại là nội dung mẫu. Bật xuất bản chỉ làm văn bản xuất hiện trên prototype, không đồng nghĩa đã được phê duyệt pháp lý.</div></form>`;
  openModal('Chỉnh sửa văn bản pháp lý',body,`<button class="btn btn-outline" data-action="close-modal">Hủy</button><button class="btn" data-action="save-legal-document">Lưu văn bản</button>`);
}
